contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 betLimitValue, uint256 wagerValue) public payable {
        require(address(this).balance >= wagerValue, "not enough balance");

        c.AdjustBetAmounts(betLimitValue);
        c.OpenToThePublic();

        uint256 balanceBefore = address(c).balance;
        bool wagered = c.hasPlayerWagered(address(this));

        bool reverted;
        try c.wager{value: wagerValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        bool wageredAfter = c.hasPlayerWagered(address(this));

        if (wagerValue == betLimitValue) {
            assert(!reverted);
            assert(balanceAfter == balanceBefore + wagerValue);
            assert(wageredAfter);
            assert(c.hasPlayerWagered(address(this)) == (wagerValue > 0));
        } else {
            assert(reverted);
            assert(balanceAfter == balanceBefore);
            assert(wageredAfter == wagered);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 betLimitValue, uint256 wagerValue) public payable {
        require(address(this).balance >= wagerValue, "not enough balance");

        c.AdjustBetAmounts(betLimitValue);
        c.OpenToThePublic();

        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.wager{value: wagerValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        bool wageredAfter = c.hasPlayerWagered(address(this));

        assert(
            (reverted == (wagerValue != betLimitValue)) &&
            (reverted || balanceAfter == balanceBefore + wagerValue) &&
            (!reverted == wageredAfter)
        );
    }

    receive() external payable {}
}

