contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 betLimitValue, uint256 wagerValue, bool open) public payable {
        require(address(this).balance >= wagerValue, "insufficient balance");

        c.AdjustBetAmounts(betLimitValue);

        bool openReverted;
        try c.OpenToThePublic() {
            openReverted = false;
        } catch {
            openReverted = true;
        }

        uint256 currentBetLimit = c.currentBetLimit();

        // Read the public surface before the deciding call.
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.wager{value: wagerValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        bool wageredAfter = c.hasPlayerWagered(address(this));

        // General rule: whatever the openness state, a successful wager must have used
        // exactly the current bet limit; if the contract is closed or the value differs
        // from the current bet limit, the call must not have succeeded.
        assert(
            (!reverted && wagerValue == currentBetLimit && balanceAfter == balanceBefore + wagerValue && wageredAfter) ||
            (reverted && (wagerValue != currentBetLimit || !open || openReverted))
        );
    }

    receive() external payable {}
}

